package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigInteger;
import java.nio.ByteBuffer;
import java.util.*;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;

public class TarUtils_parseOctal_TriageGen2Test {

    @Test
    public void testParseOctal_ValidSimple() {
        byte[] buffer = "000123 ".getBytes();
        // length is 7. end is 7. trailer is buffer[8] which is out of bounds if not careful.
        // Looking at the code: byte trailer = buffer[end + 1];
        // This implies the buffer must be at least length + offset + 2.
        byte[] paddedBuffer = new byte[10];
        System.arraycopy("000123 ".getBytes(), 0, paddedBuffer, 0, 7);
        paddedBuffer[8] = 0; // trailer at end + 1

        long result = TarUtils.parseOctal(paddedBuffer, 0, 7);
        assertEquals(83L, result); // 123 octal = 83 decimal
    }

    @Test
    public void testParseOctal_LeadingSpaces() {
        byte[] paddedBuffer = new byte[10];
        System.arraycopy("   0755 ".getBytes(), 0, paddedBuffer, 0, 8);
        paddedBuffer[9] = 0; 

        long result = TarUtils.parseOctal(paddedBuffer, 0, 8);
        assertEquals(493L, result); // 755 octal = 493 decimal
    }

    @Test
    public void testParseOctal_TrailingNulsAndSpaces() {
        // The logic: trailer = buffer[end + 1]
        // While trailer is 0 or ' ', end-- and trailer = buffer[end - 1]
        byte[] paddedBuffer = new byte[12];
        System.arraycopy("0123  \0 ".getBytes(), 0, paddedBuffer, 0, 8);
        paddedBuffer[9] = 0; // trailer at end + 1

        long result = TarUtils.parseOctal(paddedBuffer, 0, 8);
        assertEquals(83L, result); // 123 octal
    }

    @Test
    public void testParseOctal_ZeroBuffer() {
        byte[] paddedBuffer = new byte[5];
        paddedBuffer[0] = 0;
        paddedBuffer[1] = 0;
        paddedBuffer[2] = 0;
        paddedBuffer[3] = 0;
        paddedBuffer[4] = 0;

        long result = TarUtils.parseOctal(paddedBuffer, 0, 4);
        assertEquals(0L, result);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_LengthTooSmall() {
        byte[] buffer = new byte[5];
        TarUtils.parseOctal(buffer, 0, 1);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_InvalidDigit() {
        byte[] paddedBuffer = new byte[10];
        System.arraycopy("01283 ".getBytes(), 0, paddedBuffer, 0, 6);
        paddedBuffer[7] = 0;

        TarUtils.parseOctal(paddedBuffer, 0, 6);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_NonDigitChar() {
        byte[] paddedBuffer = new byte[10];
        System.arraycopy("012A3 ".getBytes(), 0, paddedBuffer, 0, 6);
        paddedBuffer[7] = 0;

        TarUtils.parseOctal(paddedBuffer, 0, 6);
    }

    @Test
    public void testParseOctal_Offset() {
        byte[] paddedBuffer = new byte[15];
        // "  077" at offset 5
        System.arraycopy("  077 ".getBytes(), 0, paddedBuffer, 5, 6);
        paddedBuffer[5 + 6 + 1] = 0; 

        long result = TarUtils.parseOctal(paddedBuffer, 5, 6);
        assertEquals(63L, result); // 77 octal = 63 decimal
    }

    @Test
    public void testParseOctal_MaxLong() {
        // Testing large octal string
        byte[] paddedBuffer = new byte[25];
        // "777777777777" is quite large
        byte[] content = "777777777777 ".getBytes();
        System.arraycopy(content, 0, paddedBuffer, 0, content.length);
        paddedBuffer[content.length + 1] = 0;

        long result = TarUtils.parseOctal(paddedBuffer, 0, content.length);
        // 777777777777 octal = 549755813887 decimal
        assertEquals(549755813887L, result);
    }
}
